insert into change_headers (id, ts) values (69, '2026-10-25') on duplicate key update ts = values(ts);
insert into change_descriptions (id, lang, description) values (69, 'ru', 'В Калькуляторе производства на вкладке «Все планеты» появилась таблица «Окупаемость построек и исследований Форм Жизни». Она показывает, какие уровни построек и исследований Форм жизни, повышающих добычу, быстрее всего окупаются. Постройка учитывается на своей планете, для построек Рок’тал — со скидкой Мегалита. Исследование учитывается на всех планетах. Уровни исследований, доступность в слоте, технологический бонус и снижение стоимости исследований задаются на вкладке «Формы жизни» параметров.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (69, 'en', 'The Production calculator has a new table on the "All planets" tab: "Amortisation of Life Form buildings and researches". It shows which levels of the Life Form buildings and researches that raise resource production pay for themselves fastest. A building counts on its own planet, with the Megalith discount for Rock´tal buildings. A research counts on every planet. Research levels, availability in the slot, the technology bonus and the research cost reduction are set on the "LifeForms" tab of the parameters.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (69, 'pt', 'A calculadora de produção tem uma nova tabela no separador «Todos os planetas»: «Amortização de edifícios e pesquisas das formas de vida». Mostra quais os níveis dos edifícios e pesquisas das formas de vida que aumentam a produção de recursos se pagam mais depressa. Um edifício conta no seu próprio planeta, com o desconto do Megálito para os edifícios Rock´tal. Uma pesquisa conta em todos os planetas. Os níveis das pesquisas, a disponibilidade no slot, o bónus tecnológico e a redução do custo das pesquisas definem-se no separador «Formas de vida» dos parâmetros.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (69, 'de', 'Der Produktionsrechner hat auf dem Reiter „Alle Planeten“ eine neue Tabelle: „Amortisation von Lebensform-Gebäuden und -Forschungen“. Sie zeigt, welche Stufen der Lebensform-Gebäude und -Forschungen, die die Rohstoffproduktion steigern, sich am schnellsten amortisieren. Ein Gebäude zählt auf seinem eigenen Planeten, bei Rock´tal-Gebäuden mit dem Rabatt des Megaliths. Eine Forschung zählt auf allen Planeten. Forschungsstufen, Verfügbarkeit im Slot, Technologiebonus und Senkung der Forschungskosten werden auf dem Reiter „Lebensformen“ der Parameter eingestellt.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (69, 'pl', 'W kalkulatorze produkcji na karcie „Wszystkie planety” pojawiła się tabela „Amortyzacja budynków i badań form życia”. Pokazuje, które poziomy budynków i badań form życia zwiększających wydobycie surowców zwracają się najszybciej. Budynek liczy się na swojej planecie, a budynki Rock´tal ze zniżką Megalitu. Badanie liczy się na wszystkich planetach. Poziomy badań, dostępność w slocie, bonus technologiczny i obniżkę kosztów badań ustawia się na karcie „Formy życia” parametrów.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (69, 'es', 'La calculadora de producción tiene una nueva tabla en la pestaña «Todos los planetas»: «Amortización de edificios e investigaciones de formas de vida». Muestra qué niveles de los edificios e investigaciones de formas de vida que aumentan la producción de recursos se amortizan antes. Un edificio cuenta en su propio planeta, con el descuento del Megalito para los edificios Rock´tal. Una investigación cuenta en todos los planetas. Los niveles de las investigaciones, la disponibilidad en la ranura, el bono tecnológico y la reducción del coste de investigación se ajustan en la pestaña «Formas de vida» de los parámetros.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (69, 'fr', 'Le calculateur de production a un nouveau tableau dans l''onglet « Toutes les planètes » : « Amortissement des bâtiments et recherches des formes de vie ». Il montre quels niveaux des bâtiments et recherches des formes de vie qui augmentent la production de ressources sont rentabilisés le plus vite. Un bâtiment compte sur sa propre planète, avec la réduction du Mégalithe pour les bâtiments Rock´tal. Une recherche compte sur toutes les planètes. Les niveaux des recherches, la disponibilité dans l''emplacement, le bonus technologique et la réduction du coût des recherches se règlent dans l''onglet « Formes de vie » des paramètres.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (69, 'it', 'Il calcolatore di produzione ha una nuova tabella nella scheda «Tutti i pianeti»: «Ammortamento di edifici e ricerche delle forme di vita». Mostra quali livelli degli edifici e delle ricerche delle forme di vita che aumentano la produzione di risorse si ripagano prima. Un edificio conta sul proprio pianeta, con lo sconto del Megalite per gli edifici Rock´tal. Una ricerca conta su tutti i pianeti. I livelli delle ricerche, la disponibilità nello slot, il bonus tecnologico e la riduzione del costo delle ricerche si impostano nella scheda «Forme di vita» dei parametri.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (69, 'nl', 'De productiecalculator heeft een nieuwe tabel op het tabblad "Alle planeten": "Afschrijving van levensvormgebouwen en -onderzoeken". Die toont welke niveaus van de levensvormgebouwen en -onderzoeken die de grondstofproductie verhogen zich het snelst terugverdienen. Een gebouw telt op zijn eigen planeet, voor Rock´tal-gebouwen met de korting van de Megaliet. Een onderzoek telt op alle planeten. Onderzoeksniveaus, beschikbaarheid in het slot, de technologiebonus en de verlaging van de onderzoekskosten stel je in op het tabblad "Levensvormen" van de parameters.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (69, 'sk', 'Kalkulačka produkcie má na karte „Všetky planéty“ novú tabuľku „Amortizácia budov a výskumov foriem života“. Ukazuje, ktoré úrovne budov a výskumov foriem života zvyšujúcich ťažbu surovín sa vrátia najrýchlejšie. Budova sa počíta na svojej planéte, pri budovách Rock´tal so zľavou Megalitu. Výskum sa počíta na všetkých planétach. Úrovne výskumov, dostupnosť v slote, technologický bonus a zníženie ceny výskumov sa nastavujú na karte „Formy života“ v parametroch.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (69, 'tr', 'Üretim hesaplayıcısının "Tüm gezegenler" sekmesinde yeni bir tablo var: "Yaşam formu binalarının ve araştırmalarının amortismanı". Kaynak üretimini artıran yaşam formu binalarının ve araştırmalarının hangi seviyelerinin kendini en hızlı amorti ettiğini gösterir. Bir bina kendi gezegeninde sayılır, Rock´tal binalarında Megalit indirimiyle. Bir araştırma tüm gezegenlerde sayılır. Araştırma seviyeleri, slottaki kullanılabilirlik, teknoloji bonusu ve araştırma maliyeti indirimi parametrelerin "Yaşam Formları" sekmesinde ayarlanır.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (69, 'bs', 'Kalkulator proizvodnje ima novu tabelu na kartici „Sve planete“: „Amortizacija zgrada i istraživanja oblika života“. Pokazuje koji se nivoi zgrada i istraživanja oblika života koji povećavaju proizvodnju resursa najbrže isplate. Zgrada se računa na svojoj planeti, za Rock´tal zgrade s popustom Megalita. Istraživanje se računa na svim planetama. Nivoi istraživanja, dostupnost u slotu, tehnološki bonus i smanjenje cijene istraživanja podešavaju se na kartici „Oblici života“ u parametrima.') on duplicate key update description = values(description);
